static void xl6CgenEmitWebSocketHttpBridge(XL6_Output* out)
{
    if ( out == NULL ) {
        return;
    }
    xl6OutputPuts("bool xrtWebResponseUpgradeWebSocket(xwebresponse*,xwsserver*,xwsconn**);\n", out);
    xl6OutputPuts("int xl6_xrt_http_response_upgrade_websocket(void* response,void* server)\n", out);
    xl6OutputPuts("{\n", out);
    xl6OutputPuts("    XL6_WsServer* ws=(XL6_WsServer*)server;\n", out);
    xl6OutputPuts("    xwsconn* connection=0;\n", out);
    xl6OutputPuts("    int ok=response != 0 && ws != 0 && ws->socket != 0 && xrtWebResponseUpgradeWebSocket((xwebresponse*)response,ws->socket,&connection);\n", out);
    xl6OutputPuts("    if ( ok ) { ws->started=1; }\n", out);
    xl6OutputPuts("    return ok;\n", out);
    xl6OutputPuts("}\n\n", out);
}
